-- ==============================================================================
-- MIGRACIÓN OFICIAL: BANCO DE 120 PREGUNTAS APROBADO PARA DUELO DE EQUIPOS
-- Pueblan las 120 preguntas oficiales (M1 a M15, 8 preguntas por módulo)
-- en public.online_questions_truth con sus respuestas correctas y explicaciones pedagógicas.
-- ==============================================================================

-- 1. Asegurar columnas en online_questions_truth
ALTER TABLE public.online_questions_truth
ADD COLUMN IF NOT EXISTS explanation TEXT;

-- 2. Upsert de las 120 preguntas oficiales
ON CONFLICT (id) DO UPDATE SET
    module_id = EXCLUDED.module_id,
    correct_answer = EXCLUDED.correct_answer,
    explanation = EXCLUDED.explanation;

-- 3. Verificación de seguridad RLS
ALTER TABLE public.online_questions_truth ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.online_questions_truth FROM anon, PUBLIC;
GRANT SELECT ON TABLE public.online_questions_truth TO authenticated;
